   853→### Addressables 使用规范
   854→
   855→```csharp
   856→public class AssetLoader : MonoBehaviour
   857→{
   858→    private readonly List<AsyncOperationHandle> _handles = new List<AsyncOperationHandle>();
   859→
   860→    public async Task<T> LoadAssetAsync<T>(string address) where T : Object
   861→    {
   862→        var handle = Addressables.LoadAssetAsync<T>(address);
   863→        await handle.Task;
   864→
   865→        if (handle.Status == AsyncOperationStatus.Succeeded)
   866→        {
   867→            _handles.Add(handle);
   868→            return handle.Result;
   869→        }
   870→
   871→        Debug.LogError($"Failed to load asset: {address}");
   872→        return null;
   873→    }
   874→
   875→    private void OnDestroy()
   876→    {
   877→        foreach (var handle in _handles)
   878→        {
   879→            Addressables.Release(handle);
   880→        }
   881→        _handles.Clear();
   882→    }
   883→}
