   276→
   277→            int recvLimit = FBAllianceGiftController.getInstance().m_recGiftLimit;
   278→            int recvCount = recvLimit - FBAllianceGiftController.getInstance().m_recGiftCount;
   279→            recvGiftCountText.text = Global._lang_2("ZH400042887", recvCount.ToString(), recvLimit.ToString());
