   489→        //第一版
   490→        //下载的shader，添加一个空白图形背景，对该背景虚化模糊，实时渲染，背景后object可动态展示
   491→        void getScreenShotBlurBgOld()
   492→        {
   493→            if (blurBGOld == null)
   494→            {
   495→                GGraph graph = new GGraph();
   496→                this._mainView.AddChildAt(graph, 0);
   497→                graph.setPosition(Vector2.zero);
   498→
   499→                graph.DrawRect(this._mainView.width, this._mainView.height, 1, Color.black, new Color32(10, 10, 10, 128));
   500→
   501→                if (PopupViewController.getInstance().deviceLevel != NativeCode.DEVICE_LEVEL.LOW)
   502→                {
   503→                    Material material = Resources.Load<Material>("MaskUIBlurMaterial");
   504→                    graph.displayObject.material = material;
   505→                }
   506→
   507→                blurBGOld = graph;
   508→            }
   509→            AddBlurList(blurBGOld);
   510→        }
   511→
   512→
   513→        //第二版
   514→        //使用截屏，texture2D读取屏幕固定区域像素，再对截屏做一次模糊虚化渲染。
   515→        //但该方式使用texture2D.ReadPixels时要求时机不能在渲染帧，所以取到的图片会有延时，会存在把要打开的界面也截出来
   516→        IEnumerator getScreenShotBlurBgNewTexture()
   517→        {
   518→            yield return new WaitForEndOfFrame();
   519→
   520→            Texture2D texture = new Texture2D((int)(StageCamera.main.rect.width * Screen.width), (int)(StageCamera.main.rect.height * Screen.height), TextureFormat.RGB24, false);
   521→            var re = new Rect(StageCamera.main.rect.x * Screen.width, StageCamera.main.rect.y * Screen.height, StageCamera.main.rect.width * Screen.width, StageCamera.main.rect.height * Screen.height);
   522→            texture.ReadPixels(re, 0, 0);
   523→            texture.Apply();
   524→
   525→
   526→            GImage graph = new GImage();
   527→            this._mainView.AddChildAt(graph, 0);
   528→            graph.texture = new NTexture(texture);
   529→
   530→            //调整宽屏时，截到的图片大小
   531→            if ((float)Screen.width / Screen.height > 9f / 16)
   532→            {
   533→                var _scale = 1920f / Screen.height;
   534→                graph.displayObject.gameObject.transform.localScale = new Vector3(_scale, _scale, 1);
   535→            }
   536→
   537→            BlurFilter filter = new BlurFilter(graph);
   538→            graph.filter = filter;
   539→            filter.blurSize = 0.015f;
   540→        }
